// surfList1 is a []*Note as a list.
type surfList1 []*Note

func (l surfList1) Len() int               { return len(l) }
func (l surfList1) At(i int) cellite.Value { return surfNoteValue(l[i]) }

// surfList1Of is a list's value as a []*Note.
func surfList1Of(v cellite.Value) []*Note {
	l := v.List()
	if l == nil {
		return nil
	}
	out := make([]*Note, l.Len())
	for i := range out {
		out[i] = surfNoteOf(l.At(i))
	}
	return out
}

// surfList2 is a []string as a list.
type surfList2 []string

func (l surfList2) Len() int               { return len(l) }
func (l surfList2) At(i int) cellite.Value { return cellite.StringValue(string(l[i])) }

// surfList2Of is a list's value as a []string.
func surfList2Of(v cellite.Value) []string {
	l := v.List()
	if l == nil {
		return nil
	}
	out := make([]string, l.Len())
	for i := range out {
		out[i] = string(l.At(i).String())
	}
	return out
}

